import osimport ioimport zipfileimport textwrapimport subprocessimport shleximport shutilimport requestsimport urllib3import xml.etree.ElementTree as ETfrom datetime import datetimefrom flask import Flask, request, send_file, render_template, Response, stream_with_context, jsonify# Deshabilitar warnings de SSL para labsurllib3.disable_warnings(urllib3.exceptions.InsecureRequestWarning)app = Flask(__name__)# ==============================================================================# LÓGICA DE INGENIERÍA# ==============================================================================def cidr_to_ip_mask(cidr):    if not cidr: return "0.0.0.0 0.0.0.0"    try:        if '/' not in cidr: return f"{cidr} 255.255.255.255"        ip_addr, mask_len = cidr.split('/')        mask_len = int(mask_len)        mask = (0xffffffff << (32 - mask_len)) & 0xffffffff        mask_str = ".".join(str((mask >> i) & 0xff) for i in [24, 16, 8, 0])        return f"{ip_addr} {mask_str}"    except: return f"{cidr}"def get_pa_crypto_config(profile):    # NOTA: Palo Alto NO soporta DES simple, mínimo 3DES    config = {        "DES-SHA256": {"encryption": ["3des"], "hash": ["sha256"], "esp_encryption": ["3des"], "esp_authentication": ["sha256"]},        "AES128-SHA256": {"encryption": ["aes-128-cbc"], "hash": ["sha256"], "esp_encryption": ["aes-128-cbc"], "esp_authentication": ["sha256"]},        "AES256-SHA256": {"encryption": ["aes-256-cbc"], "hash": ["sha256"], "esp_encryption": ["aes-256-cbc"], "esp_authentication": ["sha256"]},        "3DES-SHA256": {"encryption": ["3des"], "hash": ["sha256"], "esp_encryption": ["3des"], "esp_authentication": ["sha256"]},    }    return config.get(profile, config["AES128-SHA256"])def get_fg_crypto_proposal(profile):    # Mapeo de perfiles crypto para FortiGate    config = {        "DES-SHA256": "des-sha256",        "3DES-SHA256": "3des-sha256",        "AES128-SHA256": "aes128-sha256",        "AES256-SHA256": "aes256-sha256",    }    return config.get(profile, config["AES128-SHA256"])# ==============================================================================# GENERADORES DE CONTENIDO# ==============================================================================def generate_vars_content(data, pa_crypto):    fg_lan1_ip_mask = cidr_to_ip_mask(data['fg_lan1_cidr'])    fg_lan2_ip_mask = cidr_to_ip_mask(data['fg_lan2_cidr'])    fg_remote_lan1_ip_mask = cidr_to_ip_mask(data['pa_lan1_cidr'])    fg_remote_lan2_ip_mask = cidr_to_ip_mask(data['pa_lan2_cidr'])        psk = data['psk'].replace("'", "").replace('"', "")    tunnel_mask_ip = "255.255.255.255"    pa_tunnel_cidr = "/32"        return f"""    # --- GLOBAL ---    vpn_name: "{data['tunnel_name']}"    vpn_psk: "{psk}"    # --- CRYPTO ---    phase1_proposal: "{get_fg_crypto_proposal(data['crypto_profile'])}"    phase2_proposal: "{get_fg_crypto_proposal(data['crypto_profile'])}"    dh_group: "{data['dh_group']}"    pa_enc_algo: "{pa_crypto['esp_encryption'][0]}"    pa_auth_algo: "{pa_crypto['esp_authentication'][0]}"    # --- FORTIGATE VARS ---    fg_wan_intf: "{data['fg_wan_intf']}"    fg_lan1_intf: "{data['fg_lan1_intf']}"    fg_lan2_intf: "{data['fg_lan2_intf']}"    fg_wan_ip: "{data['fg_wan_ip']}"    fg_vdom: "{data.get('fg_vdom_name', 'root')}"        fg_lan1_cidr_raw: "{data['fg_lan1_cidr']}"    fg_lan2_cidr_raw: "{data['fg_lan2_cidr']}"    fg_lan1_mask: "{fg_lan1_ip_mask}"    fg_lan2_mask: "{fg_lan2_ip_mask}"    fg_remote_lan1_cidr: "{data['pa_lan1_cidr']}"    fg_remote_lan2_cidr: "{data['pa_lan2_cidr']}"    fg_remote_lan1_mask: "{fg_remote_lan1_ip_mask}"    fg_remote_lan2_mask: "{fg_remote_lan2_ip_mask}"    fg_tunnel_ip: "{data['fg_tunnel_ip']} {tunnel_mask_ip}"    fg_remote_tunnel_ip: "{data['pa_remote_tunnel_ip']} {tunnel_mask_ip}"    fg_remote_gw: "{data['pa_remote_wan_ip']}"    # --- PALO ALTO VARS ---    pa_wan_intf: "{data['pa_wan_intf']}"    pa_lan1_intf: "{data['pa_lan1_intf']}"    pa_lan2_intf: "{data['pa_lan2_intf']}"    pa_zone: "{data.get('pa_zone_name', 'VPN_Zone')}"    pa_lan_zone: "{data.get('pa_lan_zone', 'trust')}"    pa_lan2_zone: "{data.get('pa_lan2_zone', data.get('pa_lan_zone', 'trust'))}"    pa_wan_zone: "{data.get('pa_wan_zone', data.get('pa_lan_zone', 'trust'))}"    pa_lan1_cidr: "{data['pa_lan1_cidr']}"    pa_lan2_cidr: "{data['pa_lan2_cidr']}"    pa_remote_lan1_cidr: "{data['fg_lan1_cidr']}"    pa_remote_lan2_cidr: "{data['fg_lan2_cidr']}"    pa_wan_ip: "{data['pa_wan_ip']}"    pa_tunnel_ip: "{data['pa_tunnel_ip']}{pa_tunnel_cidr}"    pa_peer_ip: "{data['fg_remote_wan_ip']}"    pa_nexthop_ip: "{data['fg_remote_tunnel_ip_pa']}"    pa_provider:      ip_address: "{data['pa_mgmt_ip']}"      username: "{data['pa_user']}"      password: "{data['pa_password']}"    # --- OPTIONS ---    force_recreate: {str(data.get('force_recreate', 'off') == 'on').lower()}"""def generate_hosts_yml(data):    return f"""all:  children:    fortigates:      hosts:        forti_site_a:          ansible_host: {data['fg_mgmt_ip']}          ansible_user: "{data['fg_user']}"          ansible_password: "{data['fg_password']}"          ansible_connection: httpapi          ansible_network_os: fortinet.fortios.fortios          ansible_httpapi_use_ssl: yes          ansible_httpapi_validate_certs: no          ansible_httpapi_port: 443          ansible_command_timeout: 60          ansible_connect_timeout: 30    paloaltos:      hosts:        palo_site_b:          ansible_host: {data['pa_mgmt_ip']}          ansible_user: "{data['pa_user']}"          ansible_password: "{data['pa_password']}"          ansible_connection: local          ansible_python_interpreter: /root/venv/bin/python3"""def generate_site_yml_template():    return """---# ==============================================================================# VPN SITE-TO-SITE: FORTIGATE <-> PALO ALTO# Generado automaticamente# ==============================================================================# PLAY 0: PREPARACIÓN DEL ENTORNO- name: Instalar dependencias requeridas para Palo Alto  hosts: localhost  connection: local  gather_facts: yes  tasks:    - name: Detectar intérprete de Python      debug:        msg: "Usando Python: {{ ansible_playbook_python }}"        - name: Instalar setuptools      ansible.builtin.pip:        name: setuptools        state: latest        executable: pip3      ignore_errors: yes        - name: Instalar librerías Palo Alto (pan-python)      ansible.builtin.pip:        name:          - pan-python          - pan-os-python          - xmltodict          - requests        state: present        executable: pip3      ignore_errors: yes          - name: Verificar instalación de pan-os-python      ansible.builtin.command:        cmd: python3 -c "import pan.xapi; print('pan-os-python OK')"      register: verify_pan      changed_when: false      ignore_errors: yes          - name: Mostrar resultado de verificación      debug:        msg: "{{ verify_pan.stdout if verify_pan.rc == 0 else 'Error: pan-os-python no instalado correctamente' }}"# PLAY 1: FORTIGATE- name: Configurar Overlay FortiGate  hosts: fortigates  connection: httpapi  gather_facts: no  collections:    - fortinet.fortios    vars:__VARS_BLOCK__  tasks:    # --- ELIMINAR TÚNEL EXISTENTE (si force_recreate=true) ---    - name: "[CLEANUP] Eliminar Phase 2 existente"      fortios_vpn_ipsec_phase2_interface:        vdom: "{{ fg_vdom }}"        state: "absent"        vpn_ipsec_phase2_interface:          name: "{{ vpn_name }}-P2"      when: force_recreate | default(false) | bool      ignore_errors: yes    - name: "[CLEANUP] Eliminar Phase 1 existente"      fortios_vpn_ipsec_phase1_interface:        vdom: "{{ fg_vdom }}"        state: "absent"        vpn_ipsec_phase1_interface:          name: "{{ vpn_name }}"      when: force_recreate | default(false) | bool      ignore_errors: yes    - name: "[CLEANUP] Eliminar Interfaz Túnel existente"      fortios_system_interface:        vdom: "{{ fg_vdom }}"        state: "absent"        system_interface:          name: "{{ vpn_name }}"      when: force_recreate | default(false) | bool      ignore_errors: yes    # --- CREAR TÚNEL ---    - name: Configurar VPN Phase 1 (IKE Gateway)      fortios_vpn_ipsec_phase1_interface:        vdom: "{{ fg_vdom }}"        state: "present"        vpn_ipsec_phase1_interface:          name: "{{ vpn_name }}"          interface: "{{ fg_wan_intf }}"           ike_version: "2"          peertype: "any"          net_device: "disable"          proposal: "{{ phase1_proposal }}"          dhgrp: "{{ dh_group }}"          remote_gw: "{{ fg_remote_gw }}"           psksecret: "{{ vpn_psk }}"          nattraversal: "disable"          keylife: 28800      ignore_errors: yes    - name: Configurar VPN Phase 2 (IPsec SA)      fortios_vpn_ipsec_phase2_interface:        vdom: "{{ fg_vdom }}"        state: "present"        vpn_ipsec_phase2_interface:          name: "{{ vpn_name }}-P2"          phase1name: "{{ vpn_name }}"          proposal: "{{ phase2_proposal }}"          dhgrp: "{{ dh_group }}"          keylifeseconds: 3600          src_subnet: "0.0.0.0 0.0.0.0"           dst_subnet: "0.0.0.0 0.0.0.0"          auto_negotiate: "enable"      ignore_errors: yes    - name: Configurar Interfaz Túnel (VTI)      fortios_system_interface:        vdom: "{{ fg_vdom }}"        state: "present"        system_interface:          name: "{{ vpn_name }}"          vdom: "{{ fg_vdom }}"          type: "tunnel"          interface: "{{ fg_wan_intf }}"          ip: "{{ fg_tunnel_ip }}"          remote_ip: "{{ fg_remote_tunnel_ip }}"          allowaccess: "ping"    # --- OBJETOS DE RED ---    - name: Obj LAN Remota 1      fortios_firewall_address:        vdom: "{{ fg_vdom }}"        state: "present"        firewall_address:            name: "REMOTE_LAN1_{{ fg_remote_lan1_cidr | regex_replace('/', '_') }}"            subnet: "{{ fg_remote_lan1_mask }}"     - name: Obj LAN Remota 2      fortios_firewall_address:        vdom: "{{ fg_vdom }}"        state: "present"        firewall_address:            name: "REMOTE_LAN2_{{ fg_remote_lan2_cidr | regex_replace('/', '_') }}"            subnet: "{{ fg_remote_lan2_mask }}"     - name: Obj LAN Local 1      fortios_firewall_address:        vdom: "{{ fg_vdom }}"        state: "present"        firewall_address:            name: "LOCAL_LAN1_{{ fg_lan1_cidr_raw | regex_replace('/', '_') }}"            subnet: "{{ fg_lan1_mask }}"    - name: Obj LAN Local 2      fortios_firewall_address:        vdom: "{{ fg_vdom }}"        state: "present"        firewall_address:            name: "LOCAL_LAN2_{{ fg_lan2_cidr_raw | regex_replace('/', '_') }}"            subnet: "{{ fg_lan2_mask }}"    # --- ENRUTAMIENTO ESTÁTICO ---    - name: Ruta a Remote LAN 1      fortios_router_static:        vdom: "{{ fg_vdom }}"        state: "present"        router_static:          seq_num: "10"          dst: "{{ fg_remote_lan1_mask }}"                device: "{{ vpn_name }}"    - name: Ruta a Remote LAN 2      fortios_router_static:        vdom: "{{ fg_vdom }}"        state: "present"        router_static:          seq_num: "11"          dst: "{{ fg_remote_lan2_mask }}"          device: "{{ vpn_name }}"    # --- POLÍTICAS DE FIREWALL ---    - name: Politica Salida (LAN -> VPN)      fortios_firewall_policy:        vdom: "{{ fg_vdom }}"        state: "present"        firewall_policy:          policyid: "100"          name: "LAN-to-VPN"          srcintf:            - name: "{{ fg_lan1_intf }}"            - name: "{{ fg_lan2_intf }}"          dstintf:            - name: "{{ vpn_name }}"          srcaddr:             - name: "LOCAL_LAN1_{{ fg_lan1_cidr_raw | regex_replace('/', '_') }}"            - name: "LOCAL_LAN2_{{ fg_lan2_cidr_raw | regex_replace('/', '_') }}"          dstaddr:             - name: "REMOTE_LAN1_{{ fg_remote_lan1_cidr | regex_replace('/', '_') }}"            - name: "REMOTE_LAN2_{{ fg_remote_lan2_cidr | regex_replace('/', '_') }}"          action: "accept"          schedule: "always"          service:             - name: "ALL"          nat: "disable"           logtraffic: "all"    - name: Politica Entrada (VPN -> LAN)      fortios_firewall_policy:        vdom: "{{ fg_vdom }}"        state: "present"        firewall_policy:          policyid: "101"          name: "VPN-to-LAN"          srcintf:            - name: "{{ vpn_name }}"          dstintf:            - name: "{{ fg_lan1_intf }}"            - name: "{{ fg_lan2_intf }}"          srcaddr:             - name: "REMOTE_LAN1_{{ fg_remote_lan1_cidr | regex_replace('/', '_') }}"            - name: "REMOTE_LAN2_{{ fg_remote_lan2_cidr | regex_replace('/', '_') }}"          dstaddr:             - name: "LOCAL_LAN1_{{ fg_lan1_cidr_raw | regex_replace('/', '_') }}"            - name: "LOCAL_LAN2_{{ fg_lan2_cidr_raw | regex_replace('/', '_') }}"          action: "accept"          schedule: "always"          service:             - name: "ALL"          nat: "disable"           logtraffic: "all"# PLAY 2: PALO ALTO- name: Configurar Overlay Palo Alto  hosts: paloaltos  connection: local  gather_facts: no  collections:    - paloaltonetworks.panos    vars:__VARS_BLOCK__  tasks:    # --- ELIMINAR TÚNEL EXISTENTE (si force_recreate=true) ---    - name: "[CLEANUP] Eliminar IPSec Tunnel existente"      panos_ipsec_tunnel:        provider: "{{ pa_provider }}"        name: "{{ vpn_name }}"        state: absent        commit: False      when: force_recreate | default(false) | bool      ignore_errors: yes    - name: "[CLEANUP] Eliminar IKE Gateway existente"      panos_ike_gateway:        provider: "{{ pa_provider }}"        name: "{{ vpn_name }}-GW"        state: absent        commit: False      when: force_recreate | default(false) | bool      ignore_errors: yes    - name: "[CLEANUP] Eliminar Perfil IPSec existente"      panos_ipsec_profile:        provider: "{{ pa_provider }}"        name: "{{ vpn_name }}-IPSEC"        state: absent        commit: False      when: force_recreate | default(false) | bool      ignore_errors: yes    - name: "[CLEANUP] Eliminar Perfil IKE existente"      panos_ike_crypto_profile:        provider: "{{ pa_provider }}"        name: "{{ vpn_name }}-IKE"        state: absent        commit: False      when: force_recreate | default(false) | bool      ignore_errors: yes    - name: "[CLEANUP] Eliminar Interfaz Túnel existente"      panos_tunnel:        provider: "{{ pa_provider }}"        if_name: "tunnel.1"        state: absent        commit: False      when: force_recreate | default(false) | bool      ignore_errors: yes    - name: "[CLEANUP] Commit limpieza"      paloaltonetworks.panos.panos_commit_firewall:        provider: "{{ pa_provider }}"      when: force_recreate | default(false) | bool      ignore_errors: yes    # --- CREAR TÚNEL ---    # PASO 1: Crear la zona VPN primero (necesaria para asignar el tunnel)    - name: Crear Zona VPN      panos_zone:        provider: "{{ pa_provider }}"        zone: "{{ pa_zone }}"        mode: layer3      ignore_errors: yes    # PASO 2: Crear la interfaz tunnel usando panos_tunnel (NO panos_interface)    - name: Crear Interfaz Túnel      panos_tunnel:        provider: "{{ pa_provider }}"        if_name: "tunnel.1"        ip: ["{{ pa_tunnel_ip }}"]        vr_name: "default"        zone_name: "{{ pa_zone }}"        commit: False      ignore_errors: yes    - name: Perfil IKE      panos_ike_crypto_profile:        provider: "{{ pa_provider }}"        name: "{{ vpn_name }}-IKE"        dh_group: ["group{{ dh_group }}"]        encryption: ["{{ pa_enc_algo }}"]        authentication: ["{{ pa_auth_algo }}"]        lifetime_seconds: 28800        commit: False      ignore_errors: yes    - name: Perfil IPsec      panos_ipsec_profile:        provider: "{{ pa_provider }}"        name: "{{ vpn_name }}-IPSEC"        dh_group: "group{{ dh_group }}"        esp_encryption: ["{{ pa_enc_algo }}"]        esp_authentication: ["{{ pa_auth_algo }}"]        lifetime_seconds: 3600        commit: False      ignore_errors: yes    - name: IKE Gateway      panos_ike_gateway:        provider: "{{ pa_provider }}"        name: "{{ vpn_name }}-GW"        version: "ikev2"        interface: "{{ pa_wan_intf }}"            peer_ip_value: "{{ pa_peer_ip }}"        pre_shared_key: "{{ vpn_psk }}"        ikev2_crypto_profile: "{{ vpn_name }}-IKE"        enable_liveness_check: true        liveness_check_interval: 5        commit: False      ignore_errors: yes    - name: IPSec Tunnel      panos_ipsec_tunnel:        provider: "{{ pa_provider }}"        name: "{{ vpn_name }}"        tunnel_interface: "tunnel.1"        ak_ike_gateway: "{{ vpn_name }}-GW"        ak_ipsec_crypto_profile: "{{ vpn_name }}-IPSEC"        commit: False      ignore_errors: yes    - name: Proxy ID      panos_config_element:        provider: "{{ pa_provider }}"        xpath: "/config/devices/entry[@name='localhost.localdomain']/network/tunnel/ipsec/entry[@name='{{ vpn_name }}']/auto-key/proxy-id"        element: |          <entry name="Wildcard-S2S">            <local>0.0.0.0/0</local>            <remote>0.0.0.0/0</remote>          </entry>      ignore_errors: yes    - name: Ruta Estática LAN 1 (a FG)      panos_static_route:        provider: "{{ pa_provider }}"        name: "Ruta-a-FG-LAN1"        destination: "{{ pa_remote_lan1_cidr }}"         nexthop_type: "ip-address"        nexthop: "{{ pa_nexthop_ip }}"        interface: "tunnel.1"        virtual_router: "default"      ignore_errors: yes    - name: Ruta Estática LAN 2 (a FG)      panos_static_route:        provider: "{{ pa_provider }}"        name: "Ruta-a-FG-LAN2"        destination: "{{ pa_remote_lan2_cidr }}"         nexthop_type: "ip-address"        nexthop: "{{ pa_nexthop_ip }}"        interface: "tunnel.1"        virtual_router: "default"      ignore_errors: yes    - name: Policy Trust-VPN (Salida)      panos_security_rule:        provider: "{{ pa_provider }}"        rule_name: "Permitir_Salida_{{ vpn_name }}"        source_zone: ["{{ pa_lan_zone }}", "{{ pa_lan2_zone }}"]        destination_zone: ["{{ pa_zone }}"]        source_ip: ["any"]        destination_ip: ["{{ pa_remote_lan1_cidr }}", "{{ pa_remote_lan2_cidr }}"]        action: "allow"      ignore_errors: yes    - name: Policy VPN-Trust (Entrada)      panos_security_rule:        provider: "{{ pa_provider }}"        rule_name: "Permitir_Entrada_{{ vpn_name }}"        source_zone: ["{{ pa_zone }}"]        destination_zone: ["{{ pa_lan_zone }}", "{{ pa_lan2_zone }}"]        source_ip: ["{{ pa_remote_lan1_cidr }}", "{{ pa_remote_lan2_cidr }}"]        destination_ip: ["any"]        action: "allow"      ignore_errors: yes    - name: COMMIT      paloaltonetworks.panos.panos_commit_firewall:        provider: "{{ pa_provider }}""""def generate_readme():    return """# VPN Site-to-Site Orchestrator## FortiGate <-> Palo Alto### Archivos Generados:- `hosts.yml` - Inventario de dispositivos- `site.yml` - Playbook principal- `ansible.cfg` - Configuración de Ansible### Pre-requisitos IMPORTANTES:#### 1. Ansible y Python```bash# Ansible 2.9 o superiorpip3 install ansible# Librerías Python necesariaspip3 install pan-python pan-os-python xmltodict requests setuptools```#### 2. Colecciones de Ansible```bash# Colección FortiGateansible-galaxy collection install fortinet.fortios# Colección Palo Altoansible-galaxy collection install paloaltonetworks.panos```#### 3. Verificar instalación```bash# Verificar que pan-os-python está instaladopython3 -c "import pan.xapi; print('pan-os-python OK')"# Verificar coleccionesansible-galaxy collection list```### Ejecución:```bashansible-playbook site.yml```### Troubleshooting:**Error: "Missing required library pan-os-python"**- Solución: `pip3 install pan-os-python pan-python`- Si usas virtualenv, actívalo antes: `source venv/bin/activate`**Error: "Collection fortinet.fortios not found"**- Solución: `ansible-galaxy collection install fortinet.fortios`**Error: "Connection timeout"**- Verifica conectividad: `ping <IP_DISPOSITIVO>`- Verifica puertos: FortiGate=443, PaloAlto=443- Verifica credenciales en hosts.yml### Notas:- El playbook intenta instalar dependencias automáticamente- Si falla, instálalas manualmente con los comandos de arriba- Asegúrate de tener acceso de red a los dispositivosGenerado: """ + datetime.now().strftime("%Y-%m-%d %H:%M:%S")# ==============================================================================# VERIFICACIÓN DE CONECTIVIDAD# ==============================================================================def test_connectivity(host, timeout=5):    """Prueba conectividad básica con un host"""    import socket    try:        socket.setdefaulttimeout(timeout)        socket.socket(socket.AF_INET, socket.SOCK_STREAM).connect((host, 443))        return True, "Conectado"    except socket.timeout:        return False, "Timeout"    except socket.error as e:        return False, f"Error: {str(e)}"# ==============================================================================# EXTRACCIÓN DE INFO DE DISPOSITIVOS# ==============================================================================def extract_fortigate_info(host, username, password, interfaces):    """Extrae información de interfaces de FortiGate via API REST"""    result = {        'success': False,        'error': None,        'interfaces': {}    }        try:        # Login y obtener token        login_url = f"https://{host}/logincheck"        session = requests.Session()        session.verify = False                login_data = {            'username': username,            'secretkey': password        }                resp = session.post(login_url, data=login_data, timeout=10)                # Verificar si hay CSRF token en cookies        csrf_token = None        for cookie in session.cookies:            if 'ccsrftoken' in cookie.name.lower():                csrf_token = cookie.value.strip('"')                break                if not csrf_token:            # Intentar obtener de otra forma            csrf_token = session.cookies.get('ccsrftoken', '').strip('"')                headers = {}        if csrf_token:            headers['X-CSRFTOKEN'] = csrf_token                # Obtener info de cada interfaz        for intf_name in interfaces:            api_url = f"https://{host}/api/v2/cmdb/system/interface/{intf_name}"            resp = session.get(api_url, headers=headers, timeout=10)                        if resp.status_code == 200:                data = resp.json()                if 'results' in data and len(data['results']) > 0:                    intf_data = data['results'][0]                    ip = intf_data.get('ip', '0.0.0.0 0.0.0.0')                    # Formato: "10.1.1.1 255.255.255.0" -> "10.1.1.1/24"                    if isinstance(ip, str) and ' ' in ip:                        ip_parts = ip.split()                        if len(ip_parts) == 2:                            ip_addr = ip_parts[0]                            mask = ip_parts[1]                            # Convertir máscara a CIDR                            cidr = sum(bin(int(x)).count('1') for x in mask.split('.'))                            ip = f"{ip_addr}/{cidr}"                                        result['interfaces'][intf_name] = {                        'ip': ip,                        'status': intf_data.get('status', 'unknown'),                        'type': intf_data.get('type', 'unknown')                    }            else:                result['interfaces'][intf_name] = {'ip': None, 'error': f"HTTP {resp.status_code}"}                # Logout        session.get(f"https://{host}/logout", headers=headers, timeout=5)                result['success'] = True            except requests.exceptions.Timeout:        result['error'] = "Timeout conectando a FortiGate"    except requests.exceptions.ConnectionError:        result['error'] = "No se puede conectar a FortiGate"    except Exception as e:        result['error'] = str(e)        return resultdef extract_paloalto_info(host, username, password, interfaces):    """Extrae información de interfaces de Palo Alto via API XML"""    result = {        'success': False,        'error': None,        'interfaces': {}    }        try:        # Obtener API key        keygen_url = f"https://{host}/api/?type=keygen&user={username}&password={password}"        resp = requests.get(keygen_url, verify=False, timeout=10)                if resp.status_code != 200:            result['error'] = f"Error autenticando: HTTP {resp.status_code}"            return result                # Parsear XML para obtener key        root = ET.fromstring(resp.text)        key_elem = root.find('.//key')        if key_elem is None:            result['error'] = "No se pudo obtener API key"            return result                api_key = key_elem.text                # Obtener configuración de interfaces        # Primero ethernet interfaces        config_url = f"https://{host}/api/?type=config&action=get&xpath=/config/devices/entry[@name='localhost.localdomain']/network/interface&key={api_key}"        resp = requests.get(config_url, verify=False, timeout=10)                if resp.status_code == 200:            root = ET.fromstring(resp.text)                        for intf_name in interfaces:                # Buscar en ethernet                if intf_name.startswith('ethernet'):                    # ethernet1/1 -> entry[@name='ethernet1/1']                    xpath_parts = intf_name.split('/')                    if len(xpath_parts) == 2:                        slot = xpath_parts[0]  # ethernet1                        port = xpath_parts[1]  # 1                                                # Buscar en la respuesta                        for ethernet in root.findall(f".//ethernet/entry[@name='{slot}']"):                            layer3 = ethernet.find('layer3')                            if layer3 is not None:                                for unit in layer3.findall(f".//units/entry[@name='{slot}/{port}']"):                                    ip_elem = unit.find('.//ip/entry')                                    if ip_elem is not None:                                        result['interfaces'][intf_name] = {                                            'ip': ip_elem.get('name', 'N/A'),                                            'status': 'configured',                                            'zone': None  # Se llenará después                                        }                                        break                                # También buscar IP directamente en layer3                                ip_elem = layer3.find('.//ip/entry')                                if ip_elem is not None and intf_name not in result['interfaces']:                                    result['interfaces'][intf_name] = {                                        'ip': ip_elem.get('name', 'N/A'),                                        'status': 'configured',                                        'zone': None                                    }                                if intf_name not in result['interfaces']:                    result['interfaces'][intf_name] = {'ip': None, 'zone': None, 'error': 'No encontrada'}                # Obtener info operacional (IPs)        op_url = f"https://{host}/api/?type=op&cmd=<show><interface>all</interface></show>&key={api_key}"        resp = requests.get(op_url, verify=False, timeout=10)                if resp.status_code == 200:            root = ET.fromstring(resp.text)            for entry in root.findall('.//ifnet/entry'):                name = entry.find('name')                ip = entry.find('ip')                zone = entry.find('zone')                if name is not None:                    intf_name = name.text                    if intf_name in interfaces:                        ip_text = ip.text if ip is not None and ip.text else 'N/A'                        zone_text = zone.text if zone is not None and zone.text else None                                                if intf_name in result['interfaces']:                            if ip_text != 'N/A' and ip_text != '':                                result['interfaces'][intf_name]['ip'] = ip_text                            if zone_text:                                result['interfaces'][intf_name]['zone'] = zone_text                            result['interfaces'][intf_name]['status'] = 'up'                        else:                            result['interfaces'][intf_name] = {                                'ip': ip_text if ip_text != 'N/A' else None,                                'zone': zone_text,                                'status': 'up'                            }                # Obtener zonas desde configuración (método más confiable)        zone_url = f"https://{host}/api/?type=config&action=get&xpath=/config/devices/entry[@name='localhost.localdomain']/vsys/entry[@name='vsys1']/zone&key={api_key}"        resp = requests.get(zone_url, verify=False, timeout=10)                if resp.status_code == 200:            root = ET.fromstring(resp.text)            for zone_entry in root.findall('.//entry'):                zone_name = zone_entry.get('name')                if not zone_name:                    continue                                    # Buscar interfaces en esta zona (múltiples formatos)                layer3 = zone_entry.find('.//network/layer3')                if layer3 is not None:                    # Formato 1: <member>ethernet1/1</member>                    for member in layer3.findall('member'):                        member_intf = member.text                        if member_intf and member_intf in result['interfaces']:                            result['interfaces'][member_intf]['zone'] = zone_name                                        # Formato 2: texto directo con múltiples interfaces                    # Ej: "ethernet1/1 ethernet1/2" o "[ ethernet1/1 ethernet1/2 ]"                    if layer3.text:                        text = layer3.text.strip()                        # Limpiar brackets si existen                        text = text.replace('[', '').replace(']', '').strip()                        for intf in text.split():                            intf = intf.strip().rstrip(';')                            if intf and intf in result['interfaces']:                                result['interfaces'][intf]['zone'] = zone_name                result['success'] = True            except requests.exceptions.Timeout:        result['error'] = "Timeout conectando a Palo Alto"    except requests.exceptions.ConnectionError:        result['error'] = "No se puede conectar a Palo Alto"    except ET.ParseError as e:        result['error'] = f"Error parseando respuesta XML: {e}"    except Exception as e:        result['error'] = str(e)        return resultdef extract_fortigate_vpn_config(mgmt_ip, user, password, vpn_name):    """Extrae la configuración VPN actual del FortiGate"""    result = {        'success': False,        'exists': False,        'config': {            'phase1': None,            'phase2': None,            'tunnel_intf': None,            'routes': [],            'policies': []        }    }        try:        session = requests.Session()        session.verify = False                # Login        login_url = f"https://{mgmt_ip}/logincheck"        login_data = {'username': user, 'secretkey': password}        session.post(login_url, data=login_data, timeout=10)                # CSRF Token        csrf_token = None        for cookie in session.cookies:            if 'ccsrftoken' in cookie.name.lower():                csrf_token = cookie.value.strip('"')                break        headers = {'X-CSRFTOKEN': csrf_token} if csrf_token else {}                # Phase 1        p1_url = f"https://{mgmt_ip}/api/v2/cmdb/vpn.ipsec/phase1-interface/{vpn_name}"        resp = session.get(p1_url, headers=headers, timeout=10)        if resp.status_code == 200:            data = resp.json()            if data.get('results'):                result['exists'] = True                p1 = data['results'][0]                result['config']['phase1'] = {                    'name': p1.get('name'),                    'interface': p1.get('interface'),                    'remote_gw': p1.get('remote-gw'),                    'ike_version': p1.get('ike-version'),                    'proposal': p1.get('proposal'),                    'dhgrp': p1.get('dhgrp'),                    'keylife': p1.get('keylife'),                    'nattraversal': p1.get('nattraversal')                }                # Phase 2        p2_url = f"https://{mgmt_ip}/api/v2/cmdb/vpn.ipsec/phase2-interface/{vpn_name}-P2"        resp = session.get(p2_url, headers=headers, timeout=10)        if resp.status_code == 200:            data = resp.json()            if data.get('results'):                p2 = data['results'][0]                result['config']['phase2'] = {                    'name': p2.get('name'),                    'phase1name': p2.get('phase1name'),                    'proposal': p2.get('proposal'),                    'dhgrp': p2.get('dhgrp'),                    'keylifeseconds': p2.get('keylifeseconds')                }                # Tunnel Interface        intf_url = f"https://{mgmt_ip}/api/v2/cmdb/system/interface/{vpn_name}"        resp = session.get(intf_url, headers=headers, timeout=10)        if resp.status_code == 200:            data = resp.json()            if data.get('results'):                intf = data['results'][0]                result['config']['tunnel_intf'] = {                    'name': intf.get('name'),                    'ip': intf.get('ip'),                    'remote_ip': intf.get('remote-ip'),                    'type': intf.get('type')                }                # Routes (buscar rutas que usen el tunnel)        routes_url = f"https://{mgmt_ip}/api/v2/cmdb/router/static"        resp = session.get(routes_url, headers=headers, timeout=10)        if resp.status_code == 200:            data = resp.json()            for route in data.get('results', []):                if route.get('device') == vpn_name:                    result['config']['routes'].append({                        'dst': route.get('dst'),                        'device': route.get('device')                    })                # Logout        try:            session.get(f"https://{mgmt_ip}/logout", headers=headers, timeout=5)        except:            pass                result['success'] = True            except Exception as e:        result['error'] = str(e)        return resultdef extract_paloalto_vpn_config(mgmt_ip, user, password, vpn_name):    """Extrae la configuración VPN actual del Palo Alto"""    result = {        'success': False,        'exists': False,        'config': {            'ike_profile': None,            'ipsec_profile': None,            'ike_gateway': None,            'ipsec_tunnel': None,            'tunnel_intf': None,            'routes': [],            'zone': None        }    }        try:        # Obtener API key        keygen_url = f"https://{mgmt_ip}/api/?type=keygen&user={user}&password={requests.utils.quote(password)}"        resp = requests.get(keygen_url, verify=False, timeout=10)                api_key = None        if resp.status_code == 200:            root = ET.fromstring(resp.text)            key_elem = root.find('.//key')            if key_elem is not None:                api_key = key_elem.text                if not api_key:            result['error'] = 'No se pudo obtener API key'            return result                # Usar show config running para obtener toda la config de una vez        show_url = f"https://{mgmt_ip}/api/?type=op&cmd=<show><config><running></running></config></show>&key={api_key}"        resp = requests.get(show_url, verify=False, timeout=15)                if resp.status_code == 200:            root = ET.fromstring(resp.text)                        # Buscar IKE Crypto Profile            ike_profile = root.find(f".//ike-crypto-profiles/entry[@name='{vpn_name}-IKE']")            if ike_profile is not None:                result['exists'] = True                result['config']['ike_profile'] = {                    'name': ike_profile.get('name'),                    'encryption': ike_profile.findtext('.//encryption/member', ''),                    'hash': ike_profile.findtext('.//hash/member', ''),                    'dh_group': ike_profile.findtext('.//dh-group/member', ''),                    'lifetime': ike_profile.findtext('.//lifetime/seconds', '')                }                        # Buscar IPsec Crypto Profile            ipsec_profile = root.find(f".//ipsec-crypto-profiles/entry[@name='{vpn_name}-IPSEC']")            if ipsec_profile is not None:                result['exists'] = True                result['config']['ipsec_profile'] = {                    'name': ipsec_profile.get('name'),                    'encryption': ipsec_profile.findtext('.//esp/encryption/member', ''),                    'authentication': ipsec_profile.findtext('.//esp/authentication/member', ''),                    'dh_group': ipsec_profile.findtext('.//dh-group', ''),                    'lifetime': ipsec_profile.findtext('.//lifetime/seconds', '')                }                        # Buscar IKE Gateway            ike_gw = root.find(f".//gateway/entry[@name='{vpn_name}-GW']")            if ike_gw is not None:                result['exists'] = True                result['config']['ike_gateway'] = {                    'name': ike_gw.get('name'),                    'peer_address': ike_gw.findtext('.//peer-address/ip', ''),                    'interface': ike_gw.findtext('.//local-address/interface', ''),                    'ike_version': 'ikev2' if ike_gw.find('.//protocol/version') is not None else 'ikev1'                }                        # Buscar IPsec Tunnel            ipsec_tunnel = root.find(f".//tunnel/ipsec/entry[@name='{vpn_name}']")            if ipsec_tunnel is not None:                result['exists'] = True                result['config']['ipsec_tunnel'] = {                    'name': ipsec_tunnel.get('name'),                    'tunnel_interface': ipsec_tunnel.findtext('.//tunnel-interface', ''),                }                        # Buscar Tunnel Interface            tunnel_intf = root.find(".//interface/tunnel/units/entry[@name='tunnel.1']")            if tunnel_intf is not None:                result['exists'] = True                ip_entry = tunnel_intf.find('.//ip/entry')                result['config']['tunnel_intf'] = {                    'name': 'tunnel.1',                    'ip': ip_entry.get('name') if ip_entry is not None else ''                }                        # Buscar Static Routes que usen tunnel            for route in root.findall(".//static-route/entry"):                intf = route.findtext('.//interface', '')                if 'tunnel' in intf.lower():                    result['config']['routes'].append({                        'name': route.get('name'),                        'destination': route.findtext('.//destination', ''),                        'interface': intf                    })                result['success'] = True            except Exception as e:        result['error'] = str(e)        return resultdef compare_configs(current, desired, device_type):    """Compara configuración actual vs deseada y retorna diff"""    diff = {        'skip': [],      # Ya está igual        'modify': [],    # Existe pero diferente        'create': []     # No existe    }        def normalize_dh(val):        """Normaliza valor de DH group a string simple"""        if val is None:            return ''        # Si es lista, tomar primer elemento        if isinstance(val, list):            val = val[0] if val else ''        # Convertir a string y limpiar        val = str(val).strip().replace(' ', '')        # Extraer solo números        import re        match = re.search(r'\d+', str(val))        return match.group() if match else str(val)        if device_type == 'fortigate':        # Phase 1        if current['config']['phase1']:            curr_p1 = current['config']['phase1']            curr_dh = normalize_dh(curr_p1.get('dhgrp'))            desired_dh = normalize_dh(desired.get('dh_group'))                        # Comparar remote_gw y dh_group            gw_match = curr_p1.get('remote_gw') == desired.get('remote_gw')            dh_match = curr_dh == desired_dh                        if gw_match and dh_match:                diff['skip'].append({'component': 'Phase 1', 'reason': 'Config idéntica'})            else:                changes = []                if not gw_match:                    changes.append(f"GW: {curr_p1.get('remote_gw')} → {desired.get('remote_gw')}")                if not dh_match:                    changes.append(f"DH: {curr_dh} → {desired_dh}")                diff['modify'].append({'component': 'Phase 1', 'changes': ', '.join(changes)})        else:            diff['create'].append({'component': 'Phase 1'})                # Phase 2        if current['config']['phase2']:            diff['skip'].append({'component': 'Phase 2', 'reason': 'Ya existe'})        else:            diff['create'].append({'component': 'Phase 2'})                # Tunnel Interface        if current['config']['tunnel_intf']:            diff['skip'].append({'component': 'Tunnel Interface', 'reason': 'Ya existe'})        else:            diff['create'].append({'component': 'Tunnel Interface'})                # Routes        existing_routes = len(current['config']['routes'])        if existing_routes >= 2:            diff['skip'].append({'component': f'Rutas ({existing_routes})', 'reason': 'Ya existen'})        else:            diff['create'].append({'component': f'Rutas (faltan {2-existing_routes})'})        elif device_type == 'paloalto':        # IKE Profile        if current['config']['ike_profile']:            diff['skip'].append({'component': 'IKE Crypto Profile', 'reason': 'Ya existe'})        else:            diff['create'].append({'component': 'IKE Crypto Profile'})                # IPsec Profile        if current['config']['ipsec_profile']:            diff['skip'].append({'component': 'IPsec Crypto Profile', 'reason': 'Ya existe'})        else:            diff['create'].append({'component': 'IPsec Crypto Profile'})                # IKE Gateway        if current['config']['ike_gateway']:            curr_gw = current['config']['ike_gateway']            if curr_gw.get('peer_address') == desired.get('peer_ip'):                diff['skip'].append({'component': 'IKE Gateway', 'reason': 'Config idéntica'})            else:                diff['modify'].append({'component': 'IKE Gateway', 'changes': f"Peer: {curr_gw.get('peer_address')} → {desired.get('peer_ip')}"})        else:            diff['create'].append({'component': 'IKE Gateway'})                # IPsec Tunnel        if current['config']['ipsec_tunnel']:            diff['skip'].append({'component': 'IPsec Tunnel', 'reason': 'Ya existe'})        else:            diff['create'].append({'component': 'IPsec Tunnel'})                # Tunnel Interface        if current['config']['tunnel_intf']:            diff['skip'].append({'component': 'Tunnel Interface', 'reason': 'Ya existe'})        else:            diff['create'].append({'component': 'Tunnel Interface'})                # Routes        existing_routes = len(current['config']['routes'])        if existing_routes >= 2:            diff['skip'].append({'component': f'Rutas ({existing_routes})', 'reason': 'Ya existen'})        elif existing_routes > 0:            diff['skip'].append({'component': f'Rutas ({existing_routes})', 'reason': 'Parcial'})            diff['create'].append({'component': f'Rutas (faltan {2-existing_routes})'})        else:            diff['create'].append({'component': 'Rutas (2)'})        return diff@app.route('/compare-config', methods=['POST'])def compare_config():    """Extrae y compara la configuración actual vs la deseada"""    try:        data = request.json        vpn_name = data.get('tunnel_name', 'S2S-OVERLAY')                results = {            'fortigate': {'success': False, 'exists': False, 'diff': None, 'current': None},            'paloalto': {'success': False, 'exists': False, 'diff': None, 'current': None}        }                # Extraer config FortiGate        fg_current = extract_fortigate_vpn_config(            data['fg_mgmt_ip'],            data['fg_user'],            data['fg_password'],            vpn_name        )        results['fortigate']['success'] = fg_current['success']        results['fortigate']['exists'] = fg_current['exists']        results['fortigate']['current'] = fg_current['config']                if fg_current['success']:            desired_fg = {                'remote_gw': data.get('pa_remote_wan_ip', data.get('pa_wan_ip')),                'dh_group': data.get('dh_group', '14')            }            results['fortigate']['diff'] = compare_configs(fg_current, desired_fg, 'fortigate')                # Extraer config Palo Alto        pa_current = extract_paloalto_vpn_config(            data['pa_mgmt_ip'],            data['pa_user'],            data['pa_password'],            vpn_name        )        results['paloalto']['success'] = pa_current['success']        results['paloalto']['exists'] = pa_current['exists']        results['paloalto']['current'] = pa_current['config']                if pa_current['success']:            desired_pa = {                'peer_ip': data.get('fg_remote_wan_ip', data.get('fg_wan_ip'))            }            results['paloalto']['diff'] = compare_configs(pa_current, desired_pa, 'paloalto')                return jsonify(results)    except Exception as e:        return jsonify({'error': str(e)}), 500# ==============================================================================# RUTAS DEL SERVIDOR FLASK# ==============================================================================@app.route('/')def index():    return render_template('frontend.html')@app.route('/install-dependencies', methods=['POST'])def install_dependencies():    """Instala y verifica todas las dependencias necesarias"""    def generate_install_log():        try:            yield "[INFO] Iniciando instalación de dependencias...\n"            yield "=" * 60 + "\n"                        # 1. Verificar pip            yield "[STEP 1/5] Verificando pip...\n"            try:                result = subprocess.run(                    ["pip3", "--version"],                    capture_output=True,                    text=True,                    timeout=10                )                if result.returncode == 0:                    yield f"[SUCCESS] pip3 encontrado: {result.stdout.strip()}\n"                else:                    yield "[ERROR] pip3 no está disponible\n"                    return            except Exception as e:                yield f"[ERROR] Error verificando pip: {str(e)}\n"                return                        # 2. Actualizar pip y setuptools            yield "\n[STEP 2/5] Actualizando pip y setuptools...\n"            try:                result = subprocess.run(                    ["pip3", "install", "--upgrade", "pip", "setuptools", "wheel"],                    capture_output=True,                    text=True,                    timeout=120                )                if result.returncode == 0:                    yield "[SUCCESS] pip y setuptools actualizados\n"                else:                    yield f"[WARN] Advertencia al actualizar: {result.stderr[:200]}\n"            except Exception as e:                yield f"[WARN] No se pudo actualizar pip: {str(e)}\n"                        # 3. Instalar librerías Python para Palo Alto            yield "\n[STEP 3/5] Instalando librerías Python (pan-os-python, xmltodict, requests)...\n"            packages = ["pan-python", "pan-os-python", "xmltodict", "requests"]            for package in packages:                try:                    yield f"  → Instalando {package}...\n"                    result = subprocess.run(                        ["pip3", "install", "--upgrade", package],                        capture_output=True,                        text=True,                        timeout=120                    )                    if result.returncode == 0:                        yield f"  [SUCCESS] {package} instalado correctamente\n"                    else:                        yield f"  [ERROR] Error instalando {package}: {result.stderr[:200]}\n"                except Exception as e:                    yield f"  [ERROR] Excepción instalando {package}: {str(e)}\n"                        # 4. Instalar colecciones de Ansible            yield "\n[STEP 4/5] Instalando colecciones de Ansible...\n"            collections = [                "fortinet.fortios",                "paloaltonetworks.panos"            ]            for collection in collections:                try:                    yield f"  → Instalando {collection}...\n"                    result = subprocess.run(                        ["ansible-galaxy", "collection", "install", collection, "--force"],                        capture_output=True,                        text=True,                        timeout=180                    )                    if result.returncode == 0:                        yield f"  [SUCCESS] {collection} instalado correctamente\n"                    else:                        yield f"  [WARN] Advertencia al instalar {collection}: {result.stderr[:200]}\n"                except Exception as e:                    yield f"  [ERROR] Error instalando {collection}: {str(e)}\n"                        # 5. Verificación final            yield "\n[STEP 5/5] Verificando instalación...\n"            yield "=" * 60 + "\n"                        # Verificar pan-os-python            try:                result = subprocess.run(                    ["python3", "-c", "import pan.xapi; print('pan-os-python OK')"],                    capture_output=True,                    text=True,                    timeout=10                )                if result.returncode == 0:                    yield "[SUCCESS] ✓ pan-os-python verificado correctamente\n"                else:                    yield "[ERROR] ✗ pan-os-python no se pudo importar\n"            except Exception as e:                yield f"[ERROR] Error verificando pan-os-python: {str(e)}\n"                        # Verificar xmltodict            try:                result = subprocess.run(                    ["python3", "-c", "import xmltodict; print('xmltodict OK')"],                    capture_output=True,                    text=True,                    timeout=10                )                if result.returncode == 0:                    yield "[SUCCESS] ✓ xmltodict verificado correctamente\n"                else:                    yield "[WARN] ✗ xmltodict no se pudo importar\n"            except Exception as e:                yield f"[WARN] Error verificando xmltodict: {str(e)}\n"                        # Verificar colecciones            try:                result = subprocess.run(                    ["ansible-galaxy", "collection", "list"],                    capture_output=True,                    text=True,                    timeout=10                )                if "fortinet.fortios" in result.stdout and "paloaltonetworks.panos" in result.stdout:                    yield "[SUCCESS] ✓ Colecciones de Ansible verificadas\n"                else:                    yield "[WARN] ✗ Algunas colecciones pueden no estar instaladas\n"            except Exception as e:                yield f"[WARN] Error verificando colecciones: {str(e)}\n"                        yield "\n" + "=" * 60 + "\n"            yield "[COMPLETE] Proceso de instalación finalizado\n"            yield "[INFO] Si hay errores, revisa los permisos y la conexión a internet\n"                    except Exception as e:            yield f"\n[CRITICAL ERROR] Error general: {str(e)}\n"        return Response(stream_with_context(generate_install_log()), mimetype='text/plain')@app.route('/test-connectivity', methods=['POST'])def test_devices():    """Verifica conectividad con los dispositivos antes de ejecutar"""    try:        data = request.json        results = {            'fortigate': {},            'paloalto': {}        }                # Test FortiGate        fg_ok, fg_msg = test_connectivity(data['fg_mgmt_ip'])        results['fortigate'] = {'success': fg_ok, 'message': fg_msg, 'ip': data['fg_mgmt_ip']}                # Test Palo Alto        pa_ok, pa_msg = test_connectivity(data['pa_mgmt_ip'])        results['paloalto'] = {'success': pa_ok, 'message': pa_msg, 'ip': data['pa_mgmt_ip']}                return jsonify(results)    except Exception as e:        return jsonify({'error': str(e)}), 500@app.route('/extract-info', methods=['POST'])def extract_info():    """Extrae información de interfaces de ambos dispositivos"""    try:        data = request.json        results = {            'fortigate': {'success': False, 'interfaces': {}},            'paloalto': {'success': False, 'interfaces': {}}        }                # Extraer de FortiGate        fg_interfaces = [            data.get('fg_wan_intf', 'port1'),            data.get('fg_lan1_intf', 'port2'),            data.get('fg_lan2_intf', 'port3')        ]                fg_result = extract_fortigate_info(            data['fg_mgmt_ip'],            data['fg_user'],            data['fg_password'],            fg_interfaces        )        results['fortigate'] = fg_result                # Extraer de Palo Alto        pa_interfaces = [            data.get('pa_wan_intf', 'ethernet1/1'),            data.get('pa_lan1_intf', 'ethernet1/2'),            data.get('pa_lan2_intf', 'ethernet1/3')        ]                pa_result = extract_paloalto_info(            data['pa_mgmt_ip'],            data['pa_user'],            data['pa_password'],            pa_interfaces        )        results['paloalto'] = pa_result                return jsonify(results)    except Exception as e:        return jsonify({'error': str(e)}), 500@app.route('/verify-vpn', methods=['POST'])def verify_vpn():    """Verifica el estado del túnel VPN en ambos dispositivos"""    try:        data = request.json        vpn_name = data.get('tunnel_name', 'S2S-OVERLAY')        results = {            'fortigate': {'success': False, 'status': 'unknown', 'details': {}},            'paloalto': {'success': False, 'status': 'unknown', 'details': {}}        }                # =====================        # VERIFICAR FORTIGATE        # =====================        try:            session = requests.Session()            session.verify = False                        # Login            login_url = f"https://{data['fg_mgmt_ip']}/logincheck"            login_data = {'username': data['fg_user'], 'secretkey': data['fg_password']}            resp = session.post(login_url, data=login_data, timeout=10)                        # CSRF Token            csrf_token = None            for cookie in session.cookies:                if 'ccsrftoken' in cookie.name.lower():                    csrf_token = cookie.value.strip('"')                    break                        headers = {'X-CSRFTOKEN': csrf_token} if csrf_token else {}                        # Obtener estado VPN IPsec            vpn_url = f"https://{data['fg_mgmt_ip']}/api/v2/monitor/vpn/ipsec"            resp = session.get(vpn_url, headers=headers, timeout=15)                        if resp.status_code == 200:                vpn_data = resp.json()                results['fortigate']['success'] = True                                # Buscar nuestro túnel                tunnel_found = False                for tunnel in vpn_data.get('results', []):                    if tunnel.get('name') == vpn_name or tunnel.get('p2name', '').startswith(vpn_name):                        tunnel_found = True                                                # Extraer información relevante                        phase1_status = tunnel.get('status', 'unknown')                        phase2_status = 'up' if tunnel.get('proxyid', []) else 'down'                                                incoming = tunnel.get('incoming_bytes', 0)                        outgoing = tunnel.get('outgoing_bytes', 0)                                                results['fortigate']['details'] = {                            'name': tunnel.get('name', vpn_name),                            'phase1': phase1_status,                            'phase2': phase2_status,                            'incoming_bytes': incoming,                            'outgoing_bytes': outgoing,                            'peer_ip': tunnel.get('rgwy', 'N/A'),                            'local_ip': tunnel.get('lgwy', 'N/A'),                            'proxyid': tunnel.get('proxyid', [])                        }                                                if phase1_status == 'up' and phase2_status == 'up':                            results['fortigate']['status'] = 'up'                        elif phase1_status == 'up':                            results['fortigate']['status'] = 'partial'                        else:                            results['fortigate']['status'] = 'down'                        break                                if not tunnel_found:                    results['fortigate']['status'] = 'not_found'                    results['fortigate']['details'] = {'error': f'Túnel {vpn_name} no encontrado'}            else:                results['fortigate']['details'] = {'error': f'HTTP {resp.status_code}'}                        # Logout            try:                session.get(f"https://{data['fg_mgmt_ip']}/logout", headers=headers, timeout=5)            except:                pass                        except Exception as e:            results['fortigate']['details'] = {'error': str(e)}                # =====================        # VERIFICAR PALO ALTO        # =====================        try:            # Obtener API key            keygen_url = f"https://{data['pa_mgmt_ip']}/api/?type=keygen&user={data['pa_user']}&password={requests.utils.quote(data['pa_password'])}"            resp = requests.get(keygen_url, verify=False, timeout=10)                        api_key = None            if resp.status_code == 200:                root = ET.fromstring(resp.text)                key_elem = root.find('.//key')                if key_elem is not None:                    api_key = key_elem.text                        if not api_key:                results['paloalto']['details'] = {'error': 'No se pudo obtener API key'}            else:                # Consultar IKE SA                ike_url = f"https://{data['pa_mgmt_ip']}/api/?type=op&cmd=<show><vpn><ike-sa><gateway>{vpn_name}-GW</gateway></ike-sa></vpn></show>&key={api_key}"                resp = requests.get(ike_url, verify=False, timeout=15)                                ike_status = 'down'                ike_details = {}                                if resp.status_code == 200:                    root = ET.fromstring(resp.text)                    # Buscar entries de IKE SA                    for entry in root.findall('.//entry'):                        state = entry.find('.//state')                        if state is not None:                            ike_status = 'up' if state.text == 'established' else state.text                            ike_details = {                                'state': state.text,                                'gateway': entry.find('.//gwname').text if entry.find('.//gwname') is not None else 'N/A',                                'peer': entry.find('.//peer-address').text if entry.find('.//peer-address') is not None else 'N/A'                            }                            break                                # Consultar IPsec SA                ipsec_url = f"https://{data['pa_mgmt_ip']}/api/?type=op&cmd=<show><vpn><ipsec-sa><tunnel>{vpn_name}</tunnel></ipsec-sa></vpn></show>&key={api_key}"                resp = requests.get(ipsec_url, verify=False, timeout=15)                                ipsec_status = 'down'                ipsec_details = {}                                if resp.status_code == 200:                    root = ET.fromstring(resp.text)                    for entry in root.findall('.//entry'):                        state = entry.find('.//state')                        if state is not None:                            ipsec_status = 'up' if state.text == 'active' else state.text                                                        # Obtener bytes transferidos                            encap = entry.find('.//encap')                            decap = entry.find('.//decap')                                                        ipsec_details = {                                'state': state.text,                                'tunnel': entry.find('.//name').text if entry.find('.//name') is not None else vpn_name,                                'encap_bytes': encap.text if encap is not None else '0',                                'decap_bytes': decap.text if decap is not None else '0'                            }                            break                                # Consultar estado del túnel general                tunnel_url = f"https://{data['pa_mgmt_ip']}/api/?type=op&cmd=<show><vpn><flow></flow></vpn></show>&key={api_key}"                resp = requests.get(tunnel_url, verify=False, timeout=15)                                results['paloalto']['success'] = True                results['paloalto']['details'] = {                    'ike': ike_details,                    'ipsec': ipsec_details,                    'ike_status': ike_status,                    'ipsec_status': ipsec_status                }                                if ike_status == 'up' and ipsec_status == 'up':                    results['paloalto']['status'] = 'up'                elif ike_status == 'up' or ipsec_status == 'up':                    results['paloalto']['status'] = 'partial'                else:                    results['paloalto']['status'] = 'down'                            except Exception as e:            results['paloalto']['details'] = {'error': str(e)}                return jsonify(results)    except Exception as e:        return jsonify({'error': str(e)}), 500@app.route('/generate', methods=['POST'])def generate_zip():    """Genera y descarga un ZIP con todos los archivos de configuración"""    try:        data = request.json                if "'" in data.get('psk', '') or '"' in data.get('psk', ''):            return jsonify({"error": "Error: La PSK contiene caracteres no permitidos."}), 400                # Generar contenido        pa_crypto_config = get_pa_crypto_config(data['crypto_profile'])        vars_content = generate_vars_content(data, pa_crypto_config)        vars_indented = textwrap.indent(vars_content, '    ')        site_yml_content = generate_site_yml_template().replace('__VARS_BLOCK__', vars_indented)        hosts_yml_content = generate_hosts_yml(data)        ansible_cfg_content = """[defaults]inventory=./hosts.ymlhost_key_checking=Falsetimeout=30deprecation_warnings=False"""        readme_content = generate_readme()                # Crear ZIP en memoria        zip_buffer = io.BytesIO()        with zipfile.ZipFile(zip_buffer, 'w', zipfile.ZIP_DEFLATED) as zip_file:            zip_file.writestr('hosts.yml', hosts_yml_content)            zip_file.writestr('site.yml', site_yml_content)            zip_file.writestr('ansible.cfg', ansible_cfg_content)            zip_file.writestr('README.md', readme_content)                zip_buffer.seek(0)        # Formato: YYYY-MM-DD-HHMMSS-NombreVPN.zip        timestamp = datetime.now().strftime("%Y-%m-%d-%H%M%S")        filename = f"{timestamp}-{data['tunnel_name']}.zip"                return send_file(            zip_buffer,            mimetype='application/zip',            as_attachment=True,            download_name=filename        )    except Exception as e:        return jsonify({'error': str(e)}), 500@app.route('/run', methods=['POST'])def run_playbook():    """Genera los archivos y ejecuta Ansible en streaming."""    try:        data = request.json                if "'" in data.get('psk', '') or '"' in data.get('psk', ''):            return jsonify({"error": "Error: La PSK contiene caracteres no permitidos."}), 400                # Generar contenido        pa_crypto_config = get_pa_crypto_config(data['crypto_profile'])        vars_content = generate_vars_content(data, pa_crypto_config)        vars_indented = textwrap.indent(vars_content, '    ')        site_yml_content = generate_site_yml_template().replace('__VARS_BLOCK__', vars_indented)        hosts_yml_content = generate_hosts_yml(data)        ansible_cfg_content = """[defaults]inventory=./hosts.ymlhost_key_checking=Falsetimeout=30deprecation_warnings=False"""                # Workspace único por sesión        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")        workspace = f"ansible_workspace_{timestamp}"        os.makedirs(workspace, exist_ok=True)                with open(os.path.join(workspace, "hosts.yml"), "w") as f:            f.write(hosts_yml_content)        with open(os.path.join(workspace, "site.yml"), "w") as f:            f.write(site_yml_content)        with open(os.path.join(workspace, "ansible.cfg"), "w") as f:            f.write(ansible_cfg_content)                def generate_log():            try:                cmd = ["ansible-playbook", "site.yml"]                                process = subprocess.Popen(                    cmd,                    cwd=workspace,                    stdout=subprocess.PIPE,                    stderr=subprocess.STDOUT,                    text=True,                    bufsize=1                )                                for line in process.stdout:                    yield line                                process.wait()                                if process.returncode == 0:                    yield "\n[SUCCESS] Ejecución de Ansible finalizada correctamente.\n"                else:                    yield f"\n[ERROR] Ansible finalizó con código de error: {process.returncode}\n"                                # Limpiar workspace después de la ejecución                try:                    shutil.rmtree(workspace)                    yield "[CLEANUP] Workspace temporal eliminado.\n"                except:                    yield "[CLEANUP] No se pudo eliminar el workspace temporal.\n"                                except Exception as e:                yield f"\n[CRITICAL ERROR] No se pudo ejecutar Ansible: {str(e)}\n"                return Response(stream_with_context(generate_log()), mimetype='text/plain')        except Exception as e:        return str(e), 500if __name__ == '__main__':    app.run(host='0.0.0.0', port=5000, debug=True)